```javascript
import { request } from '@/utils/axios'

/**
 * 获取外检计划全部字典
 * @returns {Promise<any>} 字典数据
 */
export async function getInspectionDicts() {
  return (
    await request({
      url: '/inspection/api/inspection-plans/dicts',
      method: 'get'
    })
  ).data
}

/**
 * 新增外检送检记录
 * @param {Object} data - 送检数据
 * @param {number} data.id - ID
 * @param {string} data.inspectionDimension - 送检维度
 * @param {string} data.itemType - 货号
 * @param {string} data.itemDesign - 设计款号
 * @param {string} data.saleLocation - 销售地
 * @param {string} data.brandCode - 品牌代码
 * @param {string} data.brandName - 品牌名称
 * @param {string} data.sellCompanyId - 销售公司ID
 * @param {string} data.squareCompanyName - 公司名称
 * @param {string} data.qcResult - QC结果
 * @param {number} data.controlStock - 控制库存
 * @param {string} data.inspectionType - 送检类型
 * @param {string} data.inspectionDeadline - 送检截止时间
 * @param {string} data.inspectionStatus - 送检状态
 * @param {string} data.createType - 创建类型
 * @param {string} data.bpmNumber - BPM编号
 * @param {string} data.inspectorName - 送检人姓名
 * @param {string} data.inspectorPhone - 送检人电话
 * @param {string} data.inspectorEmail - 送检人邮箱
 * @param {string} data.materialName - 物料名称
 * @param {string} data.materialColor - 物料颜色
 * @param {string} data.materialCategory - 物料类别
 * @param {string} data.usePeple - 使用人员
 * @param {string} data.inspectionNumber - 送检单号
 * @param {string} data.inspectionUnit - 送检单位
 * @param {string} data.inspectionUnitText - 送检单位文本
 * @param {string} data.thirdPartyLab - 第三方实验室
 * @param {string} data.season - 季节
 * @param {string} data.inspectionTime - 送检时间
 * @param {string} data.inspectionRemark - 送检备注
 * @param {string} data.executeStandard - 执行标准
 * @param {string} data.materialProcess - 物料工艺
 * @param {string} data.useSite - 使用部位
 * @param {string} data.sampleQuantity - 样品数量
 * @param {string} data.skinContact - 皮肤接触
 * @returns {Promise<any>} 创建结果
 */
export async function createInspection(data) {
  return (
    await request({
      url: '/inspection/api/inspections',
      method: 'post',
