}

/**
 * 编辑外检送检记录
 * @param {Object} data - 送检数据（包含id字段）
 * @returns {Promise<any>} 更新结果
 */
export async function updateInspection(data) {
  return (
    await request({
      url: '/inspection/api/inspections',
      method: 'put',
      data
    })
  ).data
}

/**
 * 删除外检送检记录
 * @param {Array<Object>} data - 删除数据数组
 * @param {number} data[].id - 要删除的记录ID
 * @returns {Promise<any>} 删除结果
 */
export async function deleteInspections(data) {
  return (
    await request({
      url: '/inspection/api/inspections/delete',
      method: 'post',
      data
    })
  ).data
}

/**
 * 复检操作
 * @param {Array<Object>} data - 复检数据数组
 * @param {number} data[].id - 要复检的记录ID
 * @returns {Promise<any>} 复检结果
 */
export async function repeatInspections(data) {
  return (
    await request({
      url: '/inspection/api/inspections/repeat',
      method: 'post',
      data
    })
  ).data
}

/**
 * 查询外检送检记录
 * @param {Object} params - 查询参数
 * @param {string} [params.inspectionNumber] - 送检单号
 * @param {string} [params.inspectionDimension] - 送检维度
 * @param {string} [params.itemType] - 货号
 * @param {string} [params.itemDesign] - 设计款号
 * @param {string} [params.saleLocation] - 销售地
 * @param {string} [params.brandCode] - 品牌代码
 * @param {string} [params.sellCompanyId] - 销售公司ID
 * @param {string} [params.controlStock] - 控制库存
