 * @param {string} [params.inspectionDeadlineStart] - 送检截止时间开始
 * @param {string} [params.inspectionDeadlineEnd] - 送检截止时间结束
 * @param {string} [params.createType] - 创建类型
 * @param {string} [params.createdBy] - 创建人
 * @param {string} [params.createTimeStart] - 创建时间开始
 * @param {string} [params.createTimeEnd] - 创建时间结束
 * @param {string} [params.inspectionStatus] - 送检状态
 * @param {string} [params.inspectionUnit] - 送检单位
 * @param {string} [params.thirdPartyLab] - 第三方实验室
 * @param {string} [params.season] - 季节
 * @param {string} [params.inspectionTimeStart] - 送检时间开始
 * @param {string} [params.inspectionTimeEnd] - 送检时间结束
 * @param {string} [params.inspectorName] - 送检人姓名
 * @param {string} [params.inspectorPhone] - 送检人电话
 * @param {string} [params.inspectorEmail] - 送检人邮箱
 * @param {string} [params.materialName] - 物料名称
 * @param {string} [params.qualifyFlag] - 合格标识
 * @param {string} [params.confirmBy] - 确认人
 * @param {string} [params.confirmTimeStart] - 确认时间开始
 * @param {string} [params.confirmTimeEnd] - 确认时间结束
 * @param {string} [params.resultConfirmBy] - 结果确认人
 * @param {string} [params.resultConfirmTimeStart] - 结果确认时间开始
 * @param {string} [params.resultConfirmTimeEnd] - 结果确认时间结束
 * @param {string} [params.unqualifiedScheme] - 不合格方案
 * @returns {Promise<any>} 查询结果
 */
export async function getInspections(params) {
  return (
    await request({
      url: '/inspection/api/inspections',
      method: 'get',
      params
    })
  ).data
}

/**
 * 提交外检送检记录
 * @param {Array<Object>} data - 提交数据数组
 * @param {number} data[].id - 要提交的记录ID
 * @returns {Promise<any>} 提交结果
 */
export async function submitInspections(data) {
  return (
    await request({
      url: '/inspection/api/inspections/submit',
      method: 'post',
      data
    })
  ).data
}

/**
 * 获取外检送检记录详情
 * @param {number|string} id - 记录ID
 * @returns {Promise<any>} 详情数据
 */
export async function getInspectionDetail(id) {
  return (
    await request({
      url: `/inspection/api/inspections/detail/${id}`,
      method: 'get'
    })
  ).data
}

/**
 * 确认外检送检记录
 * @param {Array<Object>} data - 确认数据数组
 * @param {number} data[].id - 记录ID
 * @param {string} data[].confirmStatus - 确认状态
 * @param {string} [data[].confirmBackReason] - 确认退回原因
 * @returns {Promise<any>} 确认结果
 */
export async function confirmInspections(data) {
  return (
    await request({
      url: '/inspection/api/inspections/confirm',
      method: 'post',
      data
    })
  ).data
}

/**
 * 退回外检送检记录
 * @param {Array<Object>} data - 退回数据数组
 * @param {number} data[].id - 记录ID
 * @param {string} data[].backReason - 退回原因
 * @returns {Promise<any>} 退回结果
 */
export async function backInspections(data) {
  return (
    await request({
      url: '/inspection/api/inspections/back',
      method: 'post',
      data
    })
  ).data
}

/**
 * 导出外检送检记录为Excel
 * @param {Object} [params] - 导出筛选参数（同查询参数）
 * @returns {Promise<any>} 导出文件
 */
export async function exportInspectionsExcel(params = {}) {
  return await request({
    url: '/inspection/api/inspections/excel-export',
    method: 'get',
    params,
    responseType: 'blob' // 用于文件下载
  })
}

/**
 * 上传检验报告
 * @param {FormData} formData - 表单数据
 * @param {File} formData.file - 报告文件
 * @param {string} formData.inspectionNumber - 送检单号
 * @param {string} formData.reportNumber - 外检报告编号
 * @param {string} formData.qualifyFlag - 是否合格（1-合格，0-不合格）
 * @returns {Promise<any>} 上传结果
 */
export async function uploadInspectionReport(formData) {
  return (
    await request({
      url: '/inspection/api/inspections/upload-report',
      method: 'post',
      data: formData,
      headers: {
        'Content-Type': 'multipart/form-data'
      }
    })
  ).data
}

/**
 * 下载检验文件
 * @param {number|string} fileId - 文件ID
 * @returns {Promise<any>} 文件数据
 */
export async function downloadInspectionFile(fileId) {
  return await request({
    url: `/inspection/api/inspection-files/download/${fileId}`,
    method: 'get',
    responseType: 'blob' // 用于文件下载
  })
}

/**
 * 合格结果批量确认
 * @param {Array<Object>} data - 确认数据数组
 * @param {number} data[].id - 记录ID
 * @returns {Promise<any>} 确认结果
 */
export async function batchConfirmQualifiedResult(data) {
  return (
    await request({
      url: '/inspection/api/inspections/qualified-reuslt',
      method: 'post',
      data
    })
  ).data
}

/**
 * PDF下载
 * @param {Array<Object>} data - 下载数据数组
 * @param {number} data[].id - 记录ID
 * @returns {Promise<any>} PDF文件
 */
export async function downloadInspectionsPDF(data) {
  return await request({
    url: '/inspection/api/inspections/pdf-dowload',
    method: 'post',
    data,
    responseType: 'blob' // 用于文件下载
  })
}

/**
 * Word下载
 * @param {Array<Object>} data - 下载数据数组
 * @param {number} data[].id - 记录ID
 * @returns {Promise<any>} Word文件
 */
export async function downloadInspectionsWord(data) {
  return await request({
    url: '/inspection/api/inspections/word-dowload',
    method: 'post',
    data,
    responseType: 'blob' // 用于文件下载
  })
}
