// 登录函数
async function loginAndGetToken() {
  const response = await fetch('https://jiangsu.codemoss.vip/luomacode-api/user/login', {
    method: 'POST',
    headers: { ...COMMON_HEADERS, origin: 'https://pc.aihao123.cn' },
    body: JSON.stringify({
      email: '893917884@qq.com',
      password: 'qqlcx5'
    })
  });

  if (!response.ok) {
    throw new Error(`登录失败: ${response.status} ${response.statusText}`);
  }

  const data = await response.json();
  if (data.code === 0 && data.loginToken) {
    return data.loginToken;
  }
  throw new Error('登录返回数据格式错误');
}

// Token验证中间件
async function authenticateToken(req, res, next) {
  const authHeader = req.headers['authorization'];
  const token = authHeader?.split(' ')[1];

  if (!token) {
    return res.status(401).json({
      error: {
        message: 'Missing authorization token',
        type: 'authentication_error',
        code: 'missing_token'
      }
    });
  }

  if (token === 'sk-qqlcx5') {
    let realToken = userTokenStore.get('default_user');
    if (!realToken) {
      try {
        realToken = await loginAndGetToken();
        userTokenStore.set('default_user', realToken);
        console.log('已自动登录并获取新token');
      } catch (error) {
        return res.status(401).json({
          error: {
            message: '自动登录失败，请重试',
            type: 'authentication_error',
            code: 'login_failed'
          }
        });
      }
    }
    req.mossToken = realToken;
  } else {
    req.mossToken = token;
  }
  next();
}

// 判断是否重置会话
function shouldResetConversation(messages) {
  if (!messages?.length) return false;
  const lastUserMsg = [...messages].reverse().find(m => m.role === 'user');
  return lastUserMsg?.content.trim() === '重置';
}

// 判断是否重新登录
function shouldRelogin(messages) {
  if (!messages?.length) return false;
  const lastUserMsg = [...messages].reverse().find(m => m.role === 'user');
  if (!lastUserMsg) return false;
  const content = lastUserMsg.content.trim().toLowerCase();
  return ['重新登录', 'login', '登录'].includes(content);
}

// 根据模型名称确定版本参数
function getVersionFromModel(model) {
  return model?.includes('-tmp') ? '2' : '1';
}

// 创建新会话
async function createNewConversation(token, model) {
  const response = await fetch('https://jiangsu.codemoss.vip/luomacode-api/conversation', {
    method: 'POST',
    headers: { ...COMMON_HEADERS, token },
    body: JSON.stringify({
      title: '新建问题',
      assistantId: getVersionFromModel(model),
      version: '2'
    })
  });

  if (!response.ok) {
    throw new Error(`创建会话失败: ${response.status} ${response.statusText}`);
  }

  const data = await response.json();
  if (data.code === 0 && data.list?.length > 0) {
    return data.list[0].id;
  }
  throw new Error('创建会话返回数据格式错误');
}

// 转换请求格式
function convertToMossFormat(openaiRequest, mossToken, conversationId) {
  const { messages, model } = openaiRequest;
  const userMessages = messages.filter(m => m.role === 'user');
  const prompt = userMessages.length ? userMessages[userMessages.length - 1].content : '';
  const assistantId = getVersionFromModel(model);
  const modelName = model.replace('-tmp', '');

  return {
    url: 'https://jiangsu.codemoss.vip/luomacode-api/v3/moss/completions',
    headers: { ...COMMON_HEADERS, token: mossToken },
    body: JSON.stringify({
      prompt,
      options: {
        openCot: false,
        appId: null,
        nonce: `hp_${Math.floor(Math.random() * 1e8)}`,
        conversationId,
        openaiVersion: modelName || 'gpt-4o-mini',
        datasetIds: [],
        voice: false,
        image: false,
        assistantId,
        version: '2'
      },
      apiKey: null
    })
  };
}

// 转换响应格式
function convertToOpenAIFormat(mossResponse, model = 'gpt-4o-mini') {
  return {
    id: `chatcmpl-${Math.random().toString(36).slice(2, 11)}`,
    object: 'chat.completion',
    created: Math.floor(Date.now() / 1000),
    model,
    choices: [{
      index: 0,
      message: {
        role: 'assistant',
        content: mossResponse.content || mossResponse.text || mossResponse.response || ''
      },
      finish_reason: 'stop'
    }],
    usage: {
      prompt_tokens: mossResponse.usage?.prompt_tokens || 0,
      completion_tokens: mossResponse.usage?.completion_tokens || 0,
      total_tokens: mossResponse.usage?.total_tokens || 0
    }
  };
}

// 流式响应转换
function convertToOpenAIStream(chunk, model = 'gpt-4o-mini') {
  return {
    id: `chatcmpl-${Math.random().toString(36).slice(2, 11)}`,
    object: 'chat.completion.chunk',
    created: Math.floor(Date.now() / 1000),
    model,
    choices: [{
      index: 0,
      delta: { content: chunk },
      finish_reason: null
    }]
  };
}

// 代理主接口
app.post('/v1/chat/completions', authenticateToken, async (req, res) => {
  try {
    const { stream, messages, model } = req.body;
    const userKey = req.mossToken;

    if (shouldRelogin(messages) && req.mossToken === 'sk-qqlcx5') {
      try {
        const newToken = await loginAndGetToken();
        userTokenStore.set('default_user', newToken);
        req.mossToken = newToken;

        const streamChunk = convertToOpenAIStream('账号过期，已重新登录成功，请重新提问~~', model);
        res.writeHead(200, {
          'Content-Type': 'text/event-stream',
          'Cache-Control': 'no-cache',
          'Connection': 'keep-alive',
          'Access-Control-Allow-Origin': '*'
        });
        res.write(`data: ${JSON.stringify(streamChunk)}\n\n`);
        res.write('data: [DONE]\n\n');
        res.end();
        return;
      } catch (error) {
        console.error('重新登录失败:', error);
        return res.status(500).json({
          error: {
            message: '重新登录失败，请稍后重试',
            type: 'authentication_error',
            code: 'relogin_failed'
          }
        });
      }
    }

    let conversationId = conversationStore.get(userKey);

    if (!conversationId || shouldResetConversation(messages)) {
      try {
        conversationId = await createNewConversation(req.mossToken, model);
        conversationStore.set(userKey, conversationId);

        const streamChunk = convertToOpenAIStream(`会话ID已失效，新的会话 ID: ${conversationId} 已创建 ，请重新提问~~`, model);
        res.writeHead(200, {
          'Content-Type': 'text/event-stream',
          'Cache-Control': 'no-cache',
          'Connection': 'keep-alive',
          'Access-Control-Allow-Origin': '*'
        });
        res.write(`data: ${JSON.stringify(streamChunk)}\n\n`);
        res.write('data: [DONE]\n\n');
        res.end();
        return;
      } catch (error) {
        console.error('创建新会话失败:', error);
        return res.status(500).json({
          error: {
            message: '创建会话失败，请重新发送请求重置',
            type: 'conversation_error',
            code: 'create_conversation_failed'
          }
        });
      }
    }

    const mossRequest = convertToMossFormat(req.body, req.mossToken, conversationId);

    const response = await fetch(mossRequest.url, {
      method: 'POST',
      headers: mossRequest.headers,
      body: mossRequest.body
    });

    if (!response.ok) {
      throw new Error(`Moss API error: ${response.status} ${response.statusText}`);
    }

    if (stream) {
      res.writeHead(200, {
        'Content-Type': 'text/event-stream',
        'Cache-Control': 'no-cache',
        'Connection': 'keep-alive',
        'Access-Control-Allow-Origin': '*',
        'Access-Control-Allow-Headers': 'Cache-Control'
      });

      const reader = response.body.getReader();
      const decoder = new TextDecoder('utf-8');
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;
        buffer += decoder.decode(value, { stream: true });
        let lines = buffer.split('\n');
        buffer = lines.pop();

        for (const line of lines) {
          if (!line.trim()) continue;
          try {
            const parsed = JSON.parse(line);
            if (typeof parsed?.code === 'number') {
              const errMsg = parsed.msg || parsed.content || '服务暂时不可用~~';
              const streamChunk = convertToOpenAIStream(errMsg, model);
              res.write(`data: ${JSON.stringify(streamChunk)}\n\n`);
              res.write('data: [DONE]\n\n');
              res.end();
              return;
            }
            const content = parsed?.msgItem?.theContent || '';
            const streamChunk = convertToOpenAIStream(content, model);
            res.write(`data: ${JSON.stringify(streamChunk)}\n\n`);
          } catch (e) {
            console.error('处理流数据错误:', e);
          }
        }
      }
      res.write('data: [DONE]\n\n');
      res.end();
    } else {
      const mossData = await response.json();
      const openaiResponse = convertToOpenAIFormat(mossData, model);
      res.json(openaiResponse);
    }
  } catch (error) {
    console.error('代理错误:', error);
    res.status(500).json({
      error: {
        message: error.message || 'Internal server error',
        type: 'server_error',
        code: 'proxy_error'
      }
    });
  }
});

