```javascript
async function getConversationId(currentConversationId, inputCommand, model) {
  // 判断是否需要新建会话
  if (!currentConversationId || inputCommand === "1" || inputCommand === "重置") {
    // 调用新建会话接口
    const response = await fetch("https://jiangsu.codemoss.vip/luomacode-api/conversation", {
      headers: {
        "accept": "application/json, text/plain, */*",
        "content-type": "application/json",
        "token": "你的token这里替换"
      },
      method: "POST",
      body: JSON.stringify({
        title: "新建问题",
        assistantId: 1,
        version: "2"
      })
    });
    const data = await response.json();
    if (data.code === 0 && data.list && data.list.length > 0) {
      return data.list[0].id; // 返回新建的conversationId
    } else {
      throw new Error("新建会话失败：" + JSON.stringify(data));
    }
  } else {
    // 直接使用已有的conversationId
    return currentConversationId;
  }
}

function getCompletionsParam(model) {
  // 判断completions参数
  if (model === "gpt-3.5-turbo" && model.endsWith("0-tmp")) {
    return 2;
  }
  return 1;
}

// 使用示例
(async () => {
  try {
    let conversationId = null; // 这里可以是已有的conversationId
    const inputCommand = "重置"; // 用户输入指令
    const model = "gpt-3.5-turbo0-tmp";

    conversationId = await getConversationId(conversationId, inputCommand, model);
    const completionsParam = getCompletionsParam(model);

    console.log("使用的conversationId:", conversationId);
    console.log("completions参数:", completionsParam);

    // 这里可以继续调用completions接口，传入conversationId和completionsParam
  } catch (err) {
    console.error(err);
  }
})();
```

