### **方法二：将二进制数据转换为 Base64 Data URL**

这种方法通过 `FileReader` 将 `Blob` 对象读取为 Base64 编码的 Data URL。

**Vue Options API 示例：**

```vue
<template>
  <div class="image-displayer">
    <h2>使用 Base64 Data URL 展示图片</h2>
    <div v-if="loading">加载中...</div>
    <div v-else-if="error" class="error-message">
      加载图片失败: {{ error.message }}
    </div>
    <img v-else-if="imageDataUrl" :src="imageDataUrl" alt="加载的图片" class="displayed-image">
    <div v-else>没有图片可显示。</div>
  </div>
</template>

<script>
export default {
  name: 'ImageStreamBase64',
  data() {
    return {
      imageDataUrl: null,
      loading: false,
      error: null,
    };
  },
  async mounted() {
    await this.fetchAndDisplayImageBase64();
  },
  methods: {
    async fetchAndDisplayImageBase64() {
      this.loading = true;
      this.error = null;
      try {
        const response = await fetch('http://localhost:3000/api/image-stream');

        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }

        const imageBlob = await response.blob();
        const reader = new FileReader();

        // 当文件读取完成时触发
        reader.onloadend = () => {
          this.imageDataUrl = reader.result; // reader.result 将是 Data URL (base64)
          console.log('Image Data URL created (first 50 chars):', this.imageDataUrl.substring(0, 50) + '...');
        };

        // 读取错误时触发
        reader.onerror = (e) => {
          this.error = new Error('FileReader error: ' + e.target.error.message);
          console.error('FileReader error:', e);
        };

        // 将 Blob 读取为 Data URL
        reader.readAsDataURL(imageBlob);

      } catch (e) {
        this.error = e;
        console.error('Error fetching image:', e);
      } finally {
        this.loading = false;
      }
    },
  },
};
</script>

