<script setup>
import { ref, onMounted } from 'vue';

const imageDataUrl = ref(null);
const loading = ref(false);
const error = ref(null);

const fetchAndDisplayImageBase64 = async () => {
  loading.value = true;
  error.value = null;
  try {
    const response = await fetch('http://localhost:3000/api/image-stream');

    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }

    const imageBlob = await response.blob();
    const reader = new FileReader();

    reader.onloadend = () => {
      imageDataUrl.value = reader.result;
      console.log('Image Data URL created (first 50 chars):', imageDataUrl.value.substring(0, 50) + '...');
    };

    reader.onerror = (e) => {
      error.value = new Error('FileReader error: ' + e.target.error.message);
      console.error('FileReader error:', e);
    };

    reader.readAsDataURL(imageBlob);

  } catch (e) {
    error.value = e;
    console.error('Error fetching image:', e);
  } finally {
    loading.value = false;
  }
};

onMounted(() => {
  fetchAndDisplayImageBase64();
});
</script>

