      addDialogVisible: false,
      tableData: [], // 全部数据
      carrier: "",
      airport: [], // 改为数组支持多选
      rwyNo: "",
      dataList: [],
      airportList: [], // 机场下拉选项
      airportArr: [], // 所有机场数据
      filter: [
        {
          label: "carrier",
          title: "机场四码",
          type: "select",
          options: []
        },
        {
          label: "regCode",
          title: "数据类型",
          type: "select",
          options: []
        },
        {
          label: "anaType",
          title: "导出类型",
          type: "select",
          options: []
        }
      ],
      acTypeList: [],
      allAnaType: [],
      carrierArr: [
        { label: "厦航", value: "MF" },
        { label: "河北航", value: "NS" },
        { label: "江西航", value: "RY" }
      ],
      columnList: [
        {
          field: "airport4Code",
          width: 100,
          title: "机场四码"
        },
        {
          field: "rwyNo",
          title: "跑道",
          width: 100
        },
        {
          field: "carrier",
          title: "承运人",
          width: 140
        }
      ],
      // 导出配置
      exportConfig: {
        filename: '机场跑道数据',
        sheetName: '机场数据',
        type: 'csv',
        columns: [
          { field: 'airport4Code', title: '机场四码' },
          { field: 'rwyNo', title: '跑道' },
          { field: 'carrier', title: '承运人' }
        ]
      }
    };
  },
  mounted() {
    this.getTableList();
    this.getAllAirportList(); // 初始化加载机场数据
  },
  beforeDestroy() {},
  methods: {
    // 导出功能 - 使用vxe-table内置导出
    exportEvent() {
      if (this.dataList.length === 0) {
        this.$message.warning('没有数据可以导出');
        return;
      }

      try {
        // 生成带时间戳的文件名
        const timestamp = this.formatDate(new Date(), 'yyyyMMdd_HHmmss');
        const filename = `机场跑道数据_${timestamp}`;

        this.$refs.xTable.exportData({
          filename: filename,
          sheetName: '机场数据',
          type: 'csv',
          data: this.dataList,
          columns: this.columnList.map(col => ({
            field: col.field,
            title: col.title
          }))
        }).then(() => {
          this.$message.success('导出成功');
        }).catch((error) => {
          console.error('导出失败:', error);
          this.$message.error('导出失败，请重试');
        });
      } catch (error) {
        console.error('导出异常:', error);
        this.$message.error('导出异常，请重试');
      }
    },

    // 备用导出方法 - 如果vxe-table导出有问题，可以使用这个方法
    exportEventBackup() {
      if (this.dataList.length === 0) {
        this.$message.warning('没有数据可以导出');
        return;
      }

      try {
        // 准备导出数据
        const exportData = this.dataList.map(row => ({
          '机场四码': row.airport4Code,
          '跑道': row.rwyNo,
          '承运人': row.carrier
        }));

        // 转换为CSV格式
        const csvContent = this.convertToCSV(exportData);

        // 创建下载链接
        const blob = new Blob(['\ufeff' + csvContent], { type: 'text/csv;charset=utf-8;' });
        const link = document.createElement('a');
        const url = URL.createObjectURL(blob);
        link.setAttribute('href', url);

        const timestamp = this.formatDate(new Date(), 'yyyyMMdd_HHmmss');
        link.setAttribute('download', `机场跑道数据_${timestamp}.csv`);
        link.style.visibility = 'hidden';

        document.body.appendChild(link);
        link.click();
        document.body.removeChild(link);

        this.$message.success('导出成功');
      } catch (error) {
        console.error('导出失败:', error);
        this.$message.error('导出失败，请重试');
      }
    },

    // 转换为CSV格式
    convertToCSV(data) {
      if (!data || data.length === 0) return '';

      const headers = Object.keys(data[0]);
      const csvHeaders = headers.join(',');

      const csvRows = data.map(row => 
        headers.map(header => {
          const value = row[header] || '';
          // 如果值包含逗号、引号或换行符，需要用引号包围并转义
          if (value.toString().includes(',') || value.toString().includes('"') || value.toString().includes('\n')) {
            return `"${value.toString().replace(/"/g, '""')}"`;
          }
          return value;
        }).join(',')
      );

      return [csvHeaders, ...csvRows].join('\n');
    },

    // 格式化日期
    formatDate(date, format) {
      const o = {
        'M+': date.getMonth() + 1,
        'd+': date.getDate(),
        'H+': date.getHours(),
        'm+': date.getMinutes(),
        's+': date.getSeconds(),
        'q+': Math.floor((date.getMonth() + 3) / 3),
        'S': date.getMilliseconds()
      };

      if (/(y+)/.test(format)) {
        format = format.replace(RegExp.$1, (date.getFullYear() + '').substr(4 - RegExp.$1.length));
      }

      for (let k in o) {
        if (new RegExp('(' + k + ')').test(format)) {
          format = format.replace(RegExp.$1, RegExp.$1.length === 1 ? o[k] : ('00' + o[k]).substr(('' + o[k]).length));
        }
      }
      return format;
    },

    // 带参数查询
    searchEvent() {
      this.getFilterList();
    },

    // 获取机场下拉框所有选项
    getAllAirportList() {
      this.airportLoading = true;
      this.$store
        .dispatch("baseConfig/getAllAirportList", {
          carrier: this.carrier
        })
        .then((res) => {
          if (res.status === 200 && res.data.success) {
            this.airportArr = res.data.result;
            this.airportList = this.airportArr;
          }
        })
        .catch((err) => {
          console.log(err);
        })
        .finally(() => {
          this.airportLoading = false;
        });
    },

    // 机场搜索方法
    searchAirport(query) {
      if (query !== '') {
        this.airportLoading = true;
        // 模糊查询机场
        setTimeout(() => {
          this.airportList = this.airportArr.filter(item => {
            return item.icaoCode.toLowerCase().indexOf(query.toLowerCase()) > -1;
          });
          this.airportLoading = false;
        }, 200);
      } else {
        this.airportList = this.airportArr;
      }
    },

    // 机场选择框获取焦点
    handleAirportFocus() {
      if (this.airportArr.length === 0) {
        this.getAllAirportList();
      }
      this.airportList = this.airportArr;
    },

    getTableList() {
      // 根据不同用户角色，设置承运人
      this.loading = true;
      this.$store
        .dispatch("airport/getAirportBaseRwyList")
        .then((res) => {
          this.loading = false;
          if (res.status === 200 && res.data.success) {
            let result = res.data.result;
            this.tableData = result;
            this.getFilterList();
          }
        })
        .finally(() => {
          this.loading = false;
        });
    },

    getFilterList() {
      this.dataList = this.tableData.filter((e) => {
        let flag = true;

        // 机场四码过滤 - 支持多选
        if (flag && this.airport.length > 0) {
          flag = this.airport.some(airportCode => 
            e.airport4Code.indexOf(airportCode) >= 0
          );
        }

        // 承运人过滤
        if (flag && this.carrier) {
          flag = e.carrier === this.carrier;
        }

        // 跑道过滤
        if (flag && this.rwyNo) {
          flag = e.rwyNo.indexOf(this.rwyNo) >= 0;
        }

        return flag;
      });
    }
  }
};
</script>

