import { Buffer } from "node:buffer";

export default {
  async fetch (request) {
    if (request.method === "OPTIONS") {
      return handleOPTIONS();
    }
    const errHandler = (err) => {
      console.error(err);
      return new Response(err.message, fixCors({ status: err.status ?? 500 }));
    };
    try {
      const auth = request.headers.get("Authorization");
      const apiKey = auth?.split(" ")[1];
      const assert = (success) => {
        if (!success) {
          throw new HttpError("The specified HTTP method is not allowed for the requested resource", 400);
        }
      };
      const { pathname } = new URL(request.url);

      // --- CHANGED: START ---
      // 新的路由逻辑，使用正则表达式

      // 1. 优先处理固定的 /models 路由
      if (pathname.endsWith("/models")) {
        assert(request.method === "GET");
        return handleModels(apiKey).catch(errHandler);
      }

      // 2. 处理包含模型名称的动态路由
      // 正则表达式匹配 /<model-name>/v1/<endpoint>
      const routeRegex = /^\/([\w.-]+)\/v1\/(chat\/completions|embeddings)$/;
      const match = pathname.match(routeRegex);

      if (!match) {
        throw new HttpError("404 Not Found. Use format: /<model-name>/v1/chat/completions", 404);
      }

      const modelFromUrl = match[1]; // 捕获的模型名称，例如 "gemini-1.5-pro"
      const endpoint = match[2];     // 捕获的端点，例如 "chat/completions"

      switch (endpoint) {
        case "chat/completions":
          assert(request.method === "POST");
          return handleCompletions(await request.json(), apiKey, modelFromUrl) // 传递模型名称
            .catch(errHandler);
        case "embeddings":
          assert(request.method === "POST");
          return handleEmbeddings(await request.json(), apiKey, modelFromUrl) // 传递模型名称
            .catch(errHandler);
        default:
          // 这个 default 理论上不会被触发，因为 regex 已经限制了路径
          throw new HttpError("404 Not Found", 404);
      }
      // --- CHANGED: END ---

    } catch (err) {
      return errHandler(err);
    }
  }
};

// ... (HttpError, fixCors, handleOPTIONS, BASE_URL, API_VERSION, API_CLIENT, makeHeaders) ...
