const DEFAULT_EMBEDDINGS_MODEL = "text-embedding-004";

// --- CHANGED: START ---
// 修改函数签名以接收来自 URL 的模型
async function handleEmbeddings (req, apiKey, modelFromUrl) {
  // 优先使用 URL 中的模型，否则使用请求体中的模型
  const modelIdentifier = modelFromUrl || req.model;

  if (typeof modelIdentifier !== "string") {
    throw new HttpError("Model must be provided in URL or in the request body", 400);
  }
// --- CHANGED: END ---

  let model;
  if (modelIdentifier.startsWith("models/")) {
    model = modelIdentifier;
  } else {
    // 保持原来的默认逻辑，以防万一
    let effectiveModel = modelIdentifier;
    if (!effectiveModel.startsWith("gemini-")) {
      effectiveModel = DEFAULT_EMBEDDINGS_MODEL;
    }
    model = "models/" + effectiveModel;
  }
  if (!Array.isArray(req.input)) {
    req.input = [ req.input ];
  }
  const response = await fetch(`${BASE_URL}/${API_VERSION}/${model}:batchEmbedContents`, {
    method: "POST",
    headers: makeHeaders(apiKey, { "Content-Type": "application/json" }),
    body: JSON.stringify({
      "requests": req.input.map(text => ({
        model,
        content: { parts: { text } },
        outputDimensionality: req.dimensions,
      }))
    })
  });
  let { body } = response;
  if (response.ok) {
    const { embeddings } = JSON.parse(await response.text());
    body = JSON.stringify({
      object: "list",
      data: embeddings.map(({ values }, index) => ({
        object: "embedding",
        index,
        embedding: values,
      })),
      model: modelIdentifier, // 返回用户指定的模型名
    }, null, "  ");
  }
  return new Response(body, fixCors(response));
}

